-- Backend Engineering ("The Fracture") post-game content -- "The Interview Arena" world.
-- Closes Arc XII -- Field Ops, and closes the entire Backend Engineering pathway map
-- (world index 53 of 53). 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every prior world. The world row itself already exists
-- (spine migration 20260810420000_backend_postgame_spine.sql) -- this migration only
-- adds mission content underneath it. The Fracture mystery is resolved (Act 32); this
-- module is standalone interview-question practice, each mission a self-contained "the
-- panel asks..." prompt with no ongoing incident thread. Missions still gate sequentially
-- via prerequisites for unlock purposes only -- there is no narrative dependency between
-- them.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be-interview-arena', 'world-be-interview-arena', 'interview-arena', 'Field Ops B - The Interview Arena', 'Twelve questions, asked the way a real panel asks them -- REST vs. GraphQL, why Redis is fast, what idempotency means, how to defend a live design under pushback. The answer to every single one is already in your hands, from an incident this pathway made you live through. The only new skill left is saying it out loud, clearly, under pressure.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be-interview-arena-1', 'campaign-be-interview-arena', 'say-it-out-loud', 'Say It Out Loud', 'Six of the panel''s most common questions -- REST vs. GraphQL, why Redis is fast, idempotency, isolation levels, duplicate payments, and why retries cause outages -- answered from systems you already repaired, not from a textbook.', 1),
  ('operation-be-interview-arena-2', 'campaign-be-interview-arena', 'the-last-question', 'The Last Question', 'Circuit breakers, scaling, eventual consistency, CAP, and Kafka rebalancing -- then the arena''s final ask: design a system live, out loud, and defend it against real pushback, twice.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-interview-arena-01', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-1', 'rest-vs-graphql', 'REST vs. GraphQL', 'The panel''s oldest question, and the one candidates answer worst: REST or GraphQL. Not the slogan -- the actual tradeoff, and the specific pressure that tips it one way or the other.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"rest-vs-graphql-sim"}'::jsonb, '{"xp":470,"credits":90}'::jsonb, false, 1),
  ('mission-be-interview-arena-02', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-1', 'why-redis-is-fast', 'Why Is Redis Fast?', 'Sounds like trivia. Isn''t. In-memory storage, a single-threaded event loop, and simple data structures explain the speed -- and the same properties explain exactly where that speed runs out.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"why-redis-is-fast-sim"}'::jsonb, '{"xp":472,"credits":90}'::jsonb, false, 2),
  ('mission-be-interview-arena-03', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-1', 'what-is-idempotency', 'What Is Idempotency?', 'The word candidates use constantly and define sloppily. A precise definition, why retries specifically depend on it, and one real idempotent operation next to one real non-idempotent one.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"what-is-idempotency-sim"}'::jsonb, '{"xp":474,"credits":91}'::jsonb, false, 3),
  ('mission-be-interview-arena-04', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-1', 'explain-transaction-isolation', 'Explain Transaction Isolation', 'Every isolation level closes off a specific anomaly and charges a specific price for it. "Just use Serializable" isn''t the free upgrade it sounds like.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"explain-transaction-isolation-sim"}'::jsonb, '{"xp":476,"credits":91}'::jsonb, false, 4),
  ('mission-be-interview-arena-05', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-1', 'preventing-duplicate-payments', 'How Do You Prevent Duplicate Payments?', 'The sharpest version of idempotency there is: a retried request must never become a second charge. Two mechanisms, two different layers, and neither one is a substitute for the other.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"preventing-duplicate-payments-sim"}'::jsonb, '{"xp":478,"credits":92}'::jsonb, false, 5),
  ('mission-be-interview-arena-06', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-1', 'why-retries-cause-outages', 'Why Can Retries Cause Outages?', 'A retry is supposed to make a system more reliable. Say precisely how, done wrong, it turns a small degradation into a full outage instead.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"why-retries-cause-outages-sim"}'::jsonb, '{"xp":480,"credits":92}'::jsonb, false, 6);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-interview-arena-07', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-2', 'what-is-a-circuit-breaker', 'What Is a Circuit Breaker?', 'Closed, open, half-open -- and the specific problem a circuit breaker solves that a timeout, on its own, never touches.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"what-is-a-circuit-breaker-sim"}'::jsonb, '{"xp":482,"credits":93}'::jsonb, false, 7),
  ('mission-be-interview-arena-08', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-2', 'horizontal-vs-vertical-scaling', 'Horizontal vs. Vertical Scaling?', 'A bigger box versus more boxes. The real tradeoffs of each, and the one architectural property that has to already be true before horizontal scaling works at all.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"horizontal-vs-vertical-scaling-sim"}'::jsonb, '{"xp":484,"credits":93}'::jsonb, false, 8),
  ('mission-be-interview-arena-09', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-2', 'what-is-eventual-consistency', 'What Is Eventual Consistency?', 'A precise definition, not a hand-wave -- and a real example of when accepting a stale read is a fine tradeoff, next to one where it genuinely isn''t.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"what-is-eventual-consistency-sim"}'::jsonb, '{"xp":486,"credits":94}'::jsonb, false, 9),
  ('mission-be-interview-arena-10', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-2', 'explain-cap', 'What Is CAP?', 'The theorem candidates always flatten into "pick two of three." State it precisely, and pick a real system to show the choice it actually makes.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"explain-cap-sim"}'::jsonb, '{"xp":488,"credits":94}'::jsonb, false, 10),
  ('mission-be-interview-arena-11', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-2', 'kafka-rebalancing', 'What Happens During Kafka Rebalancing?', 'What actually triggers a rebalance, what happens to work that was already in flight when it hits, and why it''s a real operational concern and not just a mechanical detail.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"kafka-rebalancing-sim"}'::jsonb, '{"xp":490,"credits":94}'::jsonb, false, 11),
  ('mission-be-interview-arena-12', 'world-be-interview-arena', 'campaign-be-interview-arena', 'operation-be-interview-arena-2', 'the-last-question', 'The Last Question', 'No incident today. Just the whiteboard, the whole campaign in your hands, and a live design under real pushback -- design a notification service, defend it twice, and mean every word.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-interview-arena-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-last-question-boss-sim"}'::jsonb, '{"xp":900,"credits":220,"badgeIds":["the-last-question"],"skillXp":{"interview_readiness":30,"system_design":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be-interview-arena-01', 1, 'mira', 'First question, and it''s the one every panel asks in some form: REST or GraphQL. They don''t want the marketing pitch -- they want to know you can actually tell when each one is correct.'),
  ('mission-be-interview-arena-01', 2, 'forge', 'You learned GraphQL under fire, not in a classroom -- back when the citizen portal needed one endpoint that could shapeshift per client instead of a dozen bespoke REST routes. That''s the real answer key: it''s never "GraphQL is more flexible," it''s naming the specific shape problem REST can''t solve without over-fetching or a pile of one-off endpoints.'),
  ('mission-be-interview-arena-01', 3, 'mira', 'Say the tradeoff, not the slogan. That''s the whole grading rubric for this entire arena, by the way -- remember it.'),

  ('mission-be-interview-arena-02', 1, 'forge', 'Panel loves this one because it sounds like trivia and isn''t. "Why is Redis fast" -- you lived this on the transit dashboard, back when the database was answering the same read a thousand times a second and losing.'),
  ('mission-be-interview-arena-02', 2, 'mira', 'Three real reasons live under that speed. And one of those same three reasons is exactly where the speed runs out -- say that part too, or the answer sounds like you memorized a blog post.'),

  ('mission-be-interview-arena-03', 1, 'mira', 'Precise definition first, always. What does idempotent actually mean -- not the consequence, the definition.'),
  ('mission-be-interview-arena-03', 2, 'forge', 'Not "safe to retry." That''s what falls out of it. Idempotent means calling an operation once or calling it fifty times leaves the system in the exact same end state. The retry doesn''t change the outcome, even though it genuinely ran again.'),
  ('mission-be-interview-arena-03', 3, 'mira', 'And why we care about it specifically: networks lie. A client that times out has no idea whether its request actually landed. Retrying is the only sane move it has left -- and it''s only safe because, and only when, the operation is idempotent.'),

  ('mission-be-interview-arena-04', 1, 'mira', 'You''ve debugged this from the inside -- lost updates, dirty reads, the whole spectrum. Now say it out loud without an incident to lean on.'),
  ('mission-be-interview-arena-04', 2, 'forge', 'Four levels, each closing off a different anomaly. Read Committed stops dirty reads. Repeatable Read locks in one snapshot for the whole transaction. Serializable closes phantom reads and write skew too -- it behaves as if every transaction ran completely alone, one at a time.'),
  ('mission-be-interview-arena-04', 3, 'mira', 'And the part people skip is right there in that sentence: "as if run one at a time" is not free. Say what it costs, or the answer just sounds like a list you memorized.'),

  ('mission-be-interview-arena-05', 1, 'mira', 'Straight follow-up from idempotency, and the sharpest version of it there is: how do you actually stop a retried request from charging someone twice?'),
  ('mission-be-interview-arena-05', 2, 'forge', 'Two different problems wearing the same name. Stopping a duplicate request from being processed twice is an idempotency key, at the application layer. Stopping a duplicate charge from ever being recorded is a unique constraint, at the ledger itself -- the backstop for when the first layer has a bug or loses a race.'),
  ('mission-be-interview-arena-05', 3, 'mira', 'Say both. And say why neither one is a substitute for the other.'),

  ('mission-be-interview-arena-06', 1, 'forge', 'You''ve caused this exact one before -- a thousand jobs failing at the same instant, every one of them retrying on identical backoff, all landing on the recovering service at the same moment.'),
  ('mission-be-interview-arena-06', 2, 'mira', 'That''s the mechanism: a retry storm. A dependency degrades a little, callers retry, the extra retry traffic degrades it further, which triggers more retries. Naive retry logic doesn''t dampen a failure -- it amplifies it. Enough amplification and a blip becomes an outage.'),

  ('mission-be-interview-arena-07', 1, 'mira', 'Direct follow-up: what actually stops a retry storm once it starts? You built the exact mechanism for this during the resilience work.'),
  ('mission-be-interview-arena-07', 2, 'forge', 'Circuit breaker. Closed: calls pass through normally, failures get counted. Cross a threshold, it opens: calls fail immediately, locally, without ever reaching the struggling dependency. After a cooldown, half-open: a small trickle of trial requests tests whether it actually recovered. Succeed and it closes again. Fail and it reopens.'),
  ('mission-be-interview-arena-07', 3, 'mira', 'The question the panel actually wants answered underneath all of that: what does it solve that a timeout alone doesn''t? That''s the part that separates a real answer from a recited diagram.'),

  ('mission-be-interview-arena-08', 1, 'forge', 'You''ve lived both sides of this one -- bigger box, then more boxes. Panel wants the tradeoffs, not just the definitions.'),
  ('mission-be-interview-arena-08', 2, 'mira', 'Vertical: same architecture, bigger machine. Simple, no code changes -- but a hard ceiling, and still one machine that can die. Horizontal: more machines running the same service, no hard ceiling in principle, redundancy for free. "For free" is doing a lot of work in that sentence -- say what has to be true first.'),

  ('mission-be-interview-arena-09', 1, 'mira', 'You''ve stood on this exact seam before -- the boundary where two different valid answers can both be true at once, briefly, and nobody notices unless it actually matters.'),
  ('mission-be-interview-arena-09', 2, 'forge', 'Eventual consistency, precisely: if no new writes happen, every replica converges to the same value -- eventually, with no promised bound on how long that takes. Not "usually correct." A formal guarantee about the destination, with none at all about the path.'),

  ('mission-be-interview-arena-10', 1, 'forge', 'This is the one candidates always flatten into "pick two of three." Say it precisely instead, or the panel will know immediately you''re reciting a diagram you don''t actually understand.'),
  ('mission-be-interview-arena-10', 2, 'mira', 'CAP: during a network partition, choose between consistency and availability. That''s it. Partition tolerance was never really optional for a real distributed system -- partitions happen whether you plan for them or not. Ground it in one real system on each side, and the answer actually lands.'),

  ('mission-be-interview-arena-11', 1, 'forge', 'You closed an actual incident on this exact mechanism. Say it now without the postmortem to lean on.'),
  ('mission-be-interview-arena-11', 2, 'mira', 'What triggers a rebalance, what happens to work that was already in flight when it hits, and why that''s a real operational concern -- not trivia for a whiteboard.'),

  ('mission-be-interview-arena-12', 1, 'mira', 'Last question. Not a trick one -- the most honest one there is. The panel says: "design a notification service." That''s it. That''s the entire prompt.'),
  ('mission-be-interview-arena-12', 2, 'forge', 'No hidden incident today. No doubled slash to file. Just you, a whiteboard, and everything this campaign already put in your hands -- queues, idempotency, retries, circuit breakers, scaling, all of it, live, out loud.'),
  ('mission-be-interview-arena-12', 3, 'mira', 'Pitch the first architecture. Then we push back, twice, for real -- and you defend it or revise it, right there, on the spot. That''s the actual job. Every panel, every time.'),
  ('mission-be-interview-arena-12', 4, 'forge', 'Nobody''s grading whether it''s the one true correct design. We''re grading whether you can say why it''s the right one, and mean it.'),
  ('mission-be-interview-arena-12', 5, 'mira', 'Forge Division doesn''t have another incident to hand you after this. Whatever comes next, you''re the one building it -- and from what I hear, something calling itself Cipher Labs is already lining up work worth doing.'),
  ('mission-be-interview-arena-12', 6, 'forge', 'Go take the last question.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be-interview-arena-01-o1', 'mission-be-interview-arena-01', 1, 'Name the real tradeoff', 'Choose the answer that names the actual tradeoff between REST and GraphQL, not the popular slogan.'),
  ('mission-be-interview-arena-02-o1', 'mission-be-interview-arena-02', 1, 'Explain the speed and the limit', 'Find the evidence that explains both why Redis is fast and where that same property becomes a real limit.'),
  ('mission-be-interview-arena-03-o1', 'mission-be-interview-arena-03', 1, 'Define idempotency precisely', 'Choose the definition and example pair that actually holds up under a precise reading.'),
  ('mission-be-interview-arena-04-o1', 'mission-be-interview-arena-04', 1, 'Defend against "just use Serializable"', 'Choose the answer that explains what Serializable actually costs, not just what it prevents.'),
  ('mission-be-interview-arena-05-o1', 'mission-be-interview-arena-05', 1, 'Name both defenses', 'Choose the combination of mechanisms that actually prevents a duplicate payment, not just a duplicate request.'),
  ('mission-be-interview-arena-06-o1', 'mission-be-interview-arena-06', 1, 'Explain the feedback loop', 'Choose the answer that names the actual mechanism by which retries can cause an outage.'),
  ('mission-be-interview-arena-07-o1', 'mission-be-interview-arena-07', 1, 'Explain what a circuit breaker adds', 'Choose the answer that explains what a circuit breaker solves that a timeout alone doesn''t.'),
  ('mission-be-interview-arena-08-o1', 'mission-be-interview-arena-08', 1, 'Name the architectural requirement', 'Choose what has to be true about a service before horizontal scaling actually works.'),
  ('mission-be-interview-arena-09-o1', 'mission-be-interview-arena-09', 1, 'Distinguish acceptable staleness from real harm', 'Find the evidence that explains why the same eventual-consistency tradeoff is fine in one case and not the other.'),
  ('mission-be-interview-arena-10-o1', 'mission-be-interview-arena-10', 1, 'State CAP precisely', 'Choose the answer that states the theorem precisely and grounds it in a real system.'),
  ('mission-be-interview-arena-11-o1', 'mission-be-interview-arena-11', 1, 'Explain why it''s a real concern', 'Find the evidence that explains why a rebalance is a real operational concern, not just bookkeeping.'),
  ('mission-be-interview-arena-12-o1', 'mission-be-interview-arena-12', 1, 'Pitch the design', 'Choose the strongest first architecture for a reliable, multi-channel notification service.'),
  ('mission-be-interview-arena-12-o2', 'mission-be-interview-arena-12', 2, 'Defend against duplicate delivery', 'Choose the correct defense against a rebalance causing the same notification to send twice.'),
  ('mission-be-interview-arena-12-o3', 'mission-be-interview-arena-12', 3, 'Defend against a downed provider', 'Choose the correct defense against a ten-minute provider outage under naive retry logic.'),
  ('mission-be-interview-arena-12-o4', 'mission-be-interview-arena-12', 4, 'Close the last question', 'Synthesize the pitch and both defenses into the complete, defended design.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be-interview-arena-01-o1-c1', 'mission-be-interview-arena-01-o1', 1, 'multiple_choice', 'The panel asks: "When would you choose GraphQL over REST, and when would you choose REST over GraphQL?" Which answer actually earns the question?', '{"question":"The panel asks: \"When would you choose GraphQL over REST, and when would you choose REST over GraphQL?\" Which answer actually earns the question?","options":[{"id":"a","text":"Always choose GraphQL -- it is strictly more powerful than REST"},{"id":"b","text":"Choose GraphQL when different clients genuinely need different shapes of the same data and over- or under-fetching is a real cost; choose REST when resources are simple, your caching story leans on plain HTTP semantics, and you would rather not own query complexity and N+1 problems inside every resolver"},{"id":"c","text":"Always choose REST -- GraphQL is only worth the complexity at companies the size of Forge''s biggest clients"},{"id":"d","text":"It does not matter -- they are interchangeable at the wire-protocol level"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-interview-arena-02-o1-c1', 'mission-be-interview-arena-02-o1', 1, 'investigation', 'The panel does not just want "because it''s in-memory." Which piece of evidence best explains both the speed and where that speed runs out?', '{"evidence":[{"id":"ev1","label":"In-memory storage","detail":"All data lives in RAM; a read or write never waits on a disk seek the way a query against Postgres''s on-disk B-tree pages sometimes does."},{"id":"ev2","label":"Single-threaded event loop","detail":"One thread executes commands one at a time, in strict order, so there is no lock contention or context-switch overhead per operation -- but it also means one genuinely slow command (an unbounded KEYS scan, a huge SORT) blocks every other client on the instance until it finishes."},{"id":"ev3","label":"Simple data structures","detail":"Strings, hashes, sorted sets and lists are implemented so common operations run in O(1) or O(log n) time -- the structures were chosen so Redis rarely has much work to do per command."},{"id":"ev4","label":"Deployment note","detail":"The transit dashboard''s Redis instance holds 40 GB of cached data on a box with 64 GB of RAM."}],"question":"Which single piece of evidence explains both the speed and the real limit, in the same mechanism?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-interview-arena-03-o1-c1', 'mission-be-interview-arena-03-o1', 1, 'multiple_choice', 'The panel asks for a precise definition, plus one real idempotent example and one real non-idempotent example. Which answer actually holds up?', '{"question":"The panel asks for a precise definition, plus one real idempotent example and one real non-idempotent example. Which answer actually holds up?","options":[{"id":"a","text":"Idempotent means fast; a POST that creates a resource is idempotent because it is a single call"},{"id":"b","text":"Idempotent means calling an operation any number of times produces the same end state as calling it once -- e.g. PUT /users/5 {status: \"active\"} is idempotent, since setting the same status again changes nothing further, while POST /payments {amount: 20} is not, since each call creates a new charge and a naive retry after a timeout can double-charge"},{"id":"c","text":"Idempotency only applies to GET requests, since only reads are ever retried"},{"id":"d","text":"An operation is idempotent if it returns the same HTTP status code every time, regardless of what it actually did server-side"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-interview-arena-04-o1-c1', 'mission-be-interview-arena-04-o1', 1, 'multiple_choice', 'The panel pushes back: "So why not just always use Serializable and stop worrying about anomalies?" What''s the correct answer?', '{"question":"The panel pushes back: \"So why not just always use Serializable and stop worrying about anomalies?\" What is the correct answer?","options":[{"id":"a","text":"You should -- Serializable has no real downside, it is just the stricter setting"},{"id":"b","text":"Serializable forces transactions to behave as if executed one at a time; under real concurrency that means more conflicts, more forced retries and aborts, and lower throughput -- it trades concurrency for correctness, so the right level is the weakest one that still prevents the anomalies your workload actually cannot tolerate"},{"id":"c","text":"Serializable only affects read-only queries, so it never touches write throughput"},{"id":"d","text":"Isolation level has no measurable performance cost in Postgres"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-interview-arena-05-o1-c1', 'mission-be-interview-arena-05-o1', 1, 'multiple_choice', 'The panel asks you to name the actual mechanism, not just the phrase "idempotency key." What combination prevents a duplicate payment end to end?', '{"question":"The panel asks you to name the actual mechanism, not just the phrase \"idempotency key.\" What combination prevents a duplicate payment end to end?","options":[{"id":"a","text":"An idempotency key alone is enough -- once the client has one, duplicate charges are impossible"},{"id":"b","text":"An idempotency key on the request path, so a retried attempt is recognized and short-circuited before reprocessing, plus a unique constraint (e.g. on idempotency_key or order_id in the charges table) so that even a race condition or a bug in the key-checking logic cannot result in two committed charge rows for the same logical payment"},{"id":"c","text":"Rate limiting the payment endpoint, since that is what actually stops duplicates"},{"id":"d","text":"Retrying with a longer timeout so the client never needs to resend"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-interview-arena-06-o1-c1', 'mission-be-interview-arena-06-o1', 1, 'multiple_choice', 'The panel asks: "Retries are supposed to make a system more reliable. How do they end up causing outages instead?" What''s the correct mechanism?', '{"question":"The panel asks: \"Retries are supposed to make a system more reliable. How do they end up causing outages instead?\" What is the correct mechanism?","options":[{"id":"a","text":"Retries never cause outages by themselves -- only the original failure does"},{"id":"b","text":"When many callers retry a degraded dependency at once, especially with synchronized backoff and no jitter, the retry traffic itself becomes a load spike -- a thundering herd -- that pushes an already-struggling dependency further down, triggering even more retries: a feedback loop that turns a small degradation into a full outage"},{"id":"c","text":"Retries cause outages only when the retry count is configured to zero"},{"id":"d","text":"Retries are dangerous exclusively because they violate idempotency"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-interview-arena-07-o1-c1', 'mission-be-interview-arena-07-o1', 1, 'multiple_choice', 'The panel asks: "A timeout already stops a caller from waiting forever on a slow dependency. What does a circuit breaker add that a timeout alone doesn''t?"', '{"question":"The panel asks: \"A timeout already stops a caller from waiting forever on a slow dependency. What does a circuit breaker add that a timeout alone does not?\"","options":[{"id":"a","text":"Nothing -- timeouts and circuit breakers solve the exact same problem"},{"id":"b","text":"A timeout only bounds how long one caller waits per call; every caller can still keep hitting the struggling dependency, one timed-out call at a time. A circuit breaker tracks failures across calls and, once a threshold is crossed, stops sending traffic to the dependency entirely for a while -- protecting the dependency itself and sparing callers from even attempting calls very likely to fail"},{"id":"c","text":"A circuit breaker replaces the need for retries entirely"},{"id":"d","text":"A circuit breaker only matters for synchronous HTTP calls, never for queues"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-interview-arena-08-o1-c1', 'mission-be-interview-arena-08-o1', 1, 'multiple_choice', 'The panel asks: "What has to be true about a service''s architecture for horizontal scaling to actually work?"', '{"question":"The panel asks: \"What has to be true about a service''s architecture for horizontal scaling to actually work?\"","options":[{"id":"a","text":"Nothing special -- any service can be horizontally scaled by just running more copies of it"},{"id":"b","text":"The service has to be effectively stateless at the instance level -- any instance must be able to serve any request, which means session state, in-flight data, or anything else a request depends on can''t live only on one specific box; shared state has to move somewhere external, like a database or a shared cache, that every instance can reach"},{"id":"c","text":"The service just needs a load balancer in front of it, regardless of how it stores state"},{"id":"d","text":"Horizontal scaling only works for read-only services"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-interview-arena-09-o1-c1', 'mission-be-interview-arena-09-o1', 1, 'investigation', 'Both features below are served by the same eventually-consistent datastore, with the same replica lag. Which piece of evidence explains why that tradeoff is fine for one and not the other?', '{"evidence":[{"id":"ev1","label":"Follower-count display","detail":"A social feature shows a creator''s follower count; after a new follow, it can take a few seconds to update for some viewers, and nobody watching notices or is harmed by the delay."},{"id":"ev2","label":"Benefit opt-out","detail":"A resident submits an opt-out from a public benefit program. If a later read reaches a stale replica, that resident can be shown as still enrolled and keep receiving payments they explicitly opted out of."},{"id":"ev3","label":"Replication mechanism","detail":"Both features are served by the same multi-region datastore, replicating asynchronously with typical replica lag under two seconds."}],"question":"Same lag, same mechanism, same couple of seconds -- which piece of evidence explains why that staleness is fine in one case and a real problem in the other?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-interview-arena-10-o1-c1', 'mission-be-interview-arena-10-o1', 1, 'multiple_choice', 'The panel says: "Everyone tells me CAP means pick two of consistency, availability, and partition tolerance. Is that right?" Give the precise answer.', '{"question":"The panel says: \"Everyone tells me CAP means pick two of consistency, availability, and partition tolerance. Is that right?\" Give the precise answer.","options":[{"id":"a","text":"Yes, that is exactly it -- pick any two of the three"},{"id":"b","text":"No -- partition tolerance is not really optional for any real distributed system, since partitions happen whether you plan for them or not. The actual choice CAP describes is what a system does during a partition: return possibly-stale data to stay available, or refuse or error to stay consistent. Concretely, a system like DynamoDB defaults toward availability during a partition (AP-leaning), while a system requiring linearizable quorum reads, like etcd, leans toward consistency (CP-leaning) and will refuse requests it cannot safely answer"},{"id":"c","text":"CAP only applies to relational databases, never to distributed key-value stores"},{"id":"d","text":"CAP says you must sacrifice partition tolerance to get both consistency and availability"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-interview-arena-11-o1-c1', 'mission-be-interview-arena-11-o1', 1, 'investigation', 'Which piece of evidence explains why a rebalance is a real operational concern, not just an internal bookkeeping detail?', '{"evidence":[{"id":"ev1","label":"Rebalance triggers","detail":"A rebalance is triggered any time consumer group membership changes -- a consumer joins, a consumer leaves cleanly, or the group coordinator declares one dead after missed heartbeats, for example during a slow deploy or a GC pause."},{"id":"ev2","label":"In-flight processing","detail":"The instant a rebalance starts, every partition in the group is revoked from its current owner before any partition is reassigned -- there is a real window where nobody owns any partition, and whatever the previous owner had processed but not yet committed is not preserved anywhere by the rebalance itself."},{"id":"ev3","label":"Team assumption","detail":"An on-call engineer assumed a rebalance was purely a metadata operation with no effect on message processing, since the topic and its data are never touched."}],"question":"Which piece of evidence explains why a rebalance is a real operational concern, not just an internal bookkeeping detail?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-interview-arena-12-o1-c1', 'mission-be-interview-arena-12-o1', 1, 'multiple_choice', 'The panel says: "Design a notification service that can send email, SMS, and push notifications to millions of users, reliably." What''s the strongest first pitch?', '{"question":"The panel says: \"Design a notification service that can send email, SMS, and push notifications to millions of users, reliably.\" What is the strongest first pitch?","options":[{"id":"a","text":"A single synchronous endpoint that loops over every recipient and calls each provider directly, inline, before responding"},{"id":"b","text":"An API that accepts a notification request and writes a durable job to a queue, tagged with an idempotency key per logical notification, with a pool of horizontally-scaled workers pulling from the queue, calling the right provider per channel, and retrying failures with backoff -- decoupling acceptance from delivery so a slow or down provider never blocks the API"},{"id":"c","text":"Store every notification directly in the database and have a client poll for new ones every second"},{"id":"d","text":"Send everything through a single global lock so notifications are always processed in exact global order"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-interview-arena-12-o2-c1', 'mission-be-interview-arena-12-o2', 1, 'multiple_choice', 'Forge pushes back: "Two worker instances pick up the same job because of a rebalance mid-processing. What actually stops that from sending the notification twice?"', '{"question":"Forge pushes back: \"Two worker instances pick up the same job because of a rebalance mid-processing. What actually stops that from sending the notification twice?\"","options":[{"id":"a","text":"Nothing needed -- queue rebalances never cause duplicate processing"},{"id":"b","text":"Make the delivery step itself idempotent: attach the same idempotency key used for the notification to the provider call where the provider supports a client-supplied dedup id, or check-and-set a \"sent\" record per notification and channel before dispatching, so a reprocessed job is recognized and skipped instead of resent"},{"id":"c","text":"Reduce the worker pool to a single instance so there is nothing left to rebalance"},{"id":"d","text":"Increase the queue''s retention so jobs are kept for longer"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-interview-arena-12-o3-c1', 'mission-be-interview-arena-12-o3', 1, 'multiple_choice', 'Mira pushes back: "The SMS provider goes down for ten minutes. Your workers keep retrying every failed send immediately. What happens, and how do you actually defend against it?"', '{"question":"Mira pushes back: \"The SMS provider goes down for ten minutes. Your workers keep retrying every failed send immediately. What happens, and how do you actually defend against it?\"","options":[{"id":"a","text":"Nothing happens -- retries always self-resolve once the provider comes back"},{"id":"b","text":"Without backoff, every worker retries the same failing calls in a tight loop -- a retry storm that can overload the provider further right as it tries to recover, and that burns worker capacity healthy channels like email and push actually need. The defense is a circuit breaker around the SMS provider (stop calling it once failures cross a threshold, let a trickle of trial calls through after a cooldown), backoff-with-jitter on retries, and a dead-letter queue for jobs that exhaust their retry budget, so SMS failures do not starve the other channels"},{"id":"c","text":"Switch entirely to synchronous calls so failures are visible immediately"},{"id":"d","text":"Delete the failed jobs so the queue does not back up"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-interview-arena-12-o4-c1', 'mission-be-interview-arena-12-o4', 1, 'boss_encounter', 'Having pitched the design and defended it against duplicate delivery and against a downed provider, state the complete, defended design.', '{"stages":[{"objectiveRef":"mission-be-interview-arena-12-o1","label":"Pitch the design"},{"objectiveRef":"mission-be-interview-arena-12-o2","label":"Defend against duplicate delivery"},{"objectiveRef":"mission-be-interview-arena-12-o3","label":"Defend against a downed provider"}],"task":"State the complete, defended design: an API that accepts a request and hands it to a durable queue, decoupling acceptance from delivery; horizontally-scaled workers pulling from that queue, each channel calling its own provider; idempotent delivery (per-notification, per-channel dedup) so a rebalance or any other retry can never double-send; and circuit breakers plus backoff-with-jitter plus a dead-letter queue around every provider, so one channel failing never starves the others. Every piece of that answer is a system this pathway already made you build or repair firsthand."}'::jsonb, '{"requiredObjectiveIds":["mission-be-interview-arena-12-o1","mission-be-interview-arena-12-o2","mission-be-interview-arena-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be-interview-arena-01-o1-c1', 'orientation', 'Neither system is "better" in the abstract -- name the specific pressure that makes one of them the right tool for a given client.', 15, 1),
  ('mission-be-interview-arena-01-o1-c1', 'solution', 'b -- GraphQL earns its extra complexity when client-shaped queries are the real problem; REST stays correct when resources are simple and plain HTTP caching semantics are already doing real work for you.', 30, 2),

  ('mission-be-interview-arena-02-o1-c1', 'orientation', 'Two of these entries are true but incomplete on their own. One explains both the speed and the ceiling in the same breath.', 15, 1),
  ('mission-be-interview-arena-02-o1-c1', 'solution', 'ev2 -- single-threaded execution avoids lock contention entirely, which is the speed; and it is the exact same property that means one slow command blocks the whole instance, which is the real limit.', 30, 2),

  ('mission-be-interview-arena-03-o1-c1', 'orientation', 'Focus on the end state after N calls versus after one call -- not on speed, not on the HTTP verb alone, not on the status code returned.', 15, 1),
  ('mission-be-interview-arena-03-o1-c1', 'solution', 'b -- idempotency is about identical end state under repetition; PUT setting an explicit value is the classic idempotent case, POST that always creates something new is the classic non-idempotent one, and that gap is exactly what makes retrying it dangerous.', 30, 2),

  ('mission-be-interview-arena-04-o1-c1', 'orientation', '"As if run one at a time" is doing a lot of work in that guarantee. Ask what enforcing it costs when transactions actually run concurrently.', 15, 1),
  ('mission-be-interview-arena-04-o1-c1', 'solution', 'b -- Serializable is correct but expensive: it prevents every anomaly by effectively serializing conflicting transactions, meaning more aborts and retries under load, so the right level is the weakest one your workload can actually tolerate, not automatically the strictest one available.', 30, 2),

  ('mission-be-interview-arena-05-o1-c1', 'orientation', 'One layer prevents the request from being reprocessed. A different layer prevents the write from being recorded twice even if the first layer has a bug or a race. Name both.', 15, 1),
  ('mission-be-interview-arena-05-o1-c1', 'solution', 'b -- the idempotency key stops the request from being handled twice at the application layer; the unique constraint is the backstop that makes a duplicate charge structurally impossible at the data layer, independent of application logic.', 30, 2),

  ('mission-be-interview-arena-06-o1-c1', 'orientation', 'The danger is not any single retry -- it is what happens when a large number of callers retry at the same moment, against the same already-weakened target.', 15, 1),
  ('mission-be-interview-arena-06-o1-c1', 'solution', 'b -- synchronized retries pile extra load onto a struggling dependency, a thundering herd, which degrades it further and triggers even more retries: a feedback loop, not an isolated event.', 30, 2),

  ('mission-be-interview-arena-07-o1-c1', 'orientation', 'A timeout is a per-call promise about how long one caller waits. Ask what happens to the dependency itself if every caller keeps making that call, one timeout at a time.', 15, 1),
  ('mission-be-interview-arena-07-o1-c1', 'solution', 'b -- timeouts bound a single call''s wait; a circuit breaker tracks failures across calls and stops sending traffic to a struggling dependency entirely for a while, protecting the dependency and sparing callers from calls very likely to fail anyway.', 30, 2),

  ('mission-be-interview-arena-08-o1-c1', 'orientation', 'Vertical scaling never had to ask this question, because there was only ever one box. Ask what breaks the moment a request can land on any of several boxes.', 15, 1),
  ('mission-be-interview-arena-08-o1-c1', 'solution', 'b -- horizontal scaling requires that any instance can serve any request, which means the service cannot rely on state that only exists on one specific box; that state has to live somewhere shared and reachable by every instance instead.', 30, 2),

  ('mission-be-interview-arena-09-o1-c1', 'orientation', 'Same lag, same mechanism, same couple of seconds. Ask what actually differs about what a stale read means to the person affected in each case.', 15, 1),
  ('mission-be-interview-arena-09-o1-c1', 'solution', 'ev2 -- a stale read on the opt-out can mean a resident keeps receiving something they explicitly declined; a stale follower count harms no one. Eventual consistency is fine when staleness is invisible or low-stakes, and wrong when a stale read causes real harm.', 30, 2),

  ('mission-be-interview-arena-10-o1-c1', 'orientation', 'Ask whether "partition tolerance" is actually a choice for a real distributed system, or something that is simply going to happen regardless of what anyone picks.', 15, 1),
  ('mission-be-interview-arena-10-o1-c1', 'solution', 'b -- partitions are not optional, so the real choice CAP describes is what happens during one: stay available with possibly-stale data, or stay consistent by refusing requests; naming a real system on each side, like DynamoDB leaning AP or etcd leaning CP, is what actually proves you understand it.', 30, 2),

  ('mission-be-interview-arena-11-o1-c1', 'orientation', 'The topic''s data is never at risk during a rebalance. Ask what is at risk: not the log, but the work a consumer had already done and not yet told Kafka about.', 15, 1),
  ('mission-be-interview-arena-11-o1-c1', 'solution', 'ev2 -- the gap between revoke and reassignment means whatever the old owner had processed but not committed gets reprocessed, or skipped if the committed offset was ahead of true progress, by whoever picks the partition up next; that is a real correctness concern, not just bookkeeping.', 30, 2),

  ('mission-be-interview-arena-12-o1-c1', 'orientation', 'The wrong answers here all couple acceptance to delivery in some way -- inline calls, polling, a global lock. Ask what decouples them.', 20, 1),
  ('mission-be-interview-arena-12-o1-c1', 'solution', 'b -- a durable queue between acceptance and delivery, with horizontally-scaled workers per channel, means a slow or down provider never blocks the API from accepting the next request.', 35, 2),

  ('mission-be-interview-arena-12-o2-c1', 'orientation', 'You have closed this exact incident before, on a different system. The fix lives at the delivery step, not at the queue-membership level.', 20, 1),
  ('mission-be-interview-arena-12-o2-c1', 'solution', 'b -- idempotent delivery, keyed per notification and channel, means a reprocessed job after any rebalance is recognized and skipped instead of resent -- the fix is at the point of sending, not at preventing rebalances from ever happening.', 35, 2),

  ('mission-be-interview-arena-12-o3-c1', 'orientation', 'Three separate problems are stacked in this pushback: no backoff, no circuit breaker, and no isolation between channels. Each needs its own answer.', 20, 1),
  ('mission-be-interview-arena-12-o3-c1', 'solution', 'b -- a circuit breaker stops hammering the down provider, backoff-with-jitter keeps retries from synchronizing into a storm, and a dead-letter queue plus per-channel isolation keeps a dead SMS provider from starving email and push.', 35, 2),

  ('mission-be-interview-arena-12-o4-c1', 'orientation', 'Every piece of this final answer already has a name from earlier in this arena -- the synthesis is just saying all three at once, correctly, in order.', 20, 1),
  ('mission-be-interview-arena-12-o4-c1', 'solution', 'A durable queue decoupling acceptance from delivery, horizontally-scaled per-channel workers, idempotent delivery to survive any rebalance, and circuit breakers with backoff-with-jitter and a dead-letter queue around every provider -- the complete, defended design.', 35, 2);
